package com.medicore.payment.controller; import com.medicore.payment.dto.*; import com.medicore.payment.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/payments") public class PaymentController {private final PaymentService service; public PaymentController(PaymentService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public PaymentResponse create(@Valid @RequestBody PaymentRequest r){return service.create(r);} @GetMapping("/{id}") public PaymentResponse find(@PathVariable Long id){return service.find(id);} @PatchMapping("/{id}/status") public PaymentResponse status(@PathVariable Long id,@RequestParam String value){return service.status(id,value);}}
